export interface ConnectorConfig {
  /** Linear API key (Bearer token) */
  linearApiKey: string;
  /** Linear Triage team UUID */
  linearTeamId: string;
  /** GitHub webhook secret for signature verification (optional, for reference) */
  githubWebhookSecret?: string;
  /** Injected fetch for testing */
  fetch?: typeof fetch;
}

export interface GitHubIssueLabel {
  id: number;
  node_id: string;
  url: string;
  name: string;
  color: string;
  default: boolean;
  description: string;
}

export interface GitHubUser {
  login: string;
}

export interface GitHubIssue {
  title: string;
  body: string | null;
  labels: GitHubIssueLabel[];
  number: number;
  user: GitHubUser;
}

export interface GitHubRepository {
  full_name: string;
}

export interface GitHubWebhookPayload {
  action: string;
  issue: GitHubIssue;
  repository: GitHubRepository;
}

export interface LinearIssueCreateResult {
  linearIssueId: string;
  linearIssueTitle: string;
}

interface LinearGraphQLResponse {
  data?: {
    issueCreate?: {
      success: boolean;
      issue?: {
        id: string;
        title: string;
      };
    };
  };
  errors?: Array<{ message: string }>;
}

function validatePayload(payload: GitHubWebhookPayload): void {
  if (!payload.action || payload.action !== 'labeled') {
    throw new Error('GitHub webhook action must be "labeled"');
  }
  if (!payload.issue) {
    throw new Error('Missing issue object in payload');
  }
  if (!payload.issue.title) {
    throw new Error('Missing issue.title');
  }
  if (payload.issue.body === null || payload.issue.body === undefined) {
    throw new Error('Missing issue.body');
  }
  if (!Array.isArray(payload.issue.labels) || payload.issue.labels.length === 0) {
    throw new Error('Missing issue.labels array');
  }
  const hasBugLabel = payload.issue.labels.some((label) => label.name === 'bug');
  if (!hasBugLabel) {
    throw new Error('Issue does not have the "bug" label');
  }
  if (typeof payload.issue.number !== 'number') {
    throw new Error('Missing issue.number');
  }
  if (!payload.issue.user || !payload.issue.user.login) {
    throw new Error('Missing issue.user.login');
  }
}

function buildGraphQLMutation(
  title: string,
  description: string,
  teamId: string,
  labels: string[],
): { query: string; variables: Record<string, never> } {
  const escapedTitle = title.replace(/"/g, '\\"');
  const escapedDescription = description.replace(/"/g, '\\"');
  const labelsArray = labels.map((l) => `"${l.replace(/"/g, '\\"')}"`).join(', ');
  const query = `mutation IssueCreate { issueCreate(input: { title: "${escapedTitle}", description: "${escapedDescription}", teamId: "${teamId}", labels: [${labelsArray}] }) { success issue { id title } } }`;
  return { query, variables: {} };
}

export async function handle(
  payload: GitHubWebhookPayload,
  config: ConnectorConfig,
): Promise<LinearIssueCreateResult> {
  validatePayload(payload);

  const { linearApiKey, linearTeamId, fetch = globalThis.fetch } = config;
  if (!linearApiKey) throw new Error('Missing linearApiKey in config');
  if (!linearTeamId) throw new Error('Missing linearTeamId in config');
  if (!fetch) throw new Error('fetch is not available');

  const labelNames = payload.issue.labels.map((l) => l.name);
  const description = `${payload.issue.body}\n\n---\nGitHub Issue: #${payload.issue.number}\nReporter: @${payload.issue.user.login}`;

  const { query, variables } = buildGraphQLMutation(
    payload.issue.title,
    description,
    linearTeamId,
    labelNames,
  );

  const response = await fetch('https://api.linear.app/graphql', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      Authorization: `Bearer ${linearApiKey}`,
    },
    body: JSON.stringify({ query, variables }),
  });

  if (!response.ok) {
    throw new Error(`Linear API request failed with status ${response.status} at POST https://api.linear.app/graphql`);
  }

  const result = (await response.json()) as LinearGraphQLResponse;

  if (result.errors && result.errors.length > 0) {
    throw new Error(`Linear API errors: ${result.errors.map((e) => e.message).join(', ')}`);
  }

  if (!result.data?.issueCreate?.success || !result.data.issueCreate.issue?.id) {
    throw new Error('Linear API did not return a successful issue creation');
  }

  return {
    linearIssueId: result.data.issueCreate.issue.id,
    linearIssueTitle: result.data.issueCreate.issue.title,
  };
}

