  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch();
    const config: ConnectorConfig = {
      linearApiKey: 'test-linear-key',
      linearTeamId: 'TRIAGE_TEAM_ID',
      fetch,
    };
    const result = await handle(SOURCE_EXAMPLE as unknown as GitHubWebhookPayload, config);
    expect(calls.length).toBeGreaterThan(0);
    expect(result.linearIssueId).toBe('LINEAR-123');
    expect(result.linearIssueTitle).toBe('Fix login button alignment');
  });
});

describe('handle', () => {
  it('creates a Linear issue with correct field mapping on happy path', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url === 'https://api.linear.app/graphql' && req.method === 'POST') {
        return jsonResponse(TARGET_ENDPOINTS[0].response, 200);
      }
      return jsonResponse({ error: 'not found' }, 404);
    });

    const payload: GitHubWebhookPayload = {
      action: 'labeled',
      issue: {
        title: 'Test issue',
        body: 'Test description',
        labels: [{ id: 1, node_id: 'n', url: '', name: 'bug', color: 'c', default: false, description: '' }],
        number: 123,
        user: { login: 'testuser' },
      },
      repository: { full_name: 'owner/repo' },
    };

    const config: ConnectorConfig = {
      linearApiKey: 'test-key',
      linearTeamId: 'TEAM-123',
      fetch,
    };

    const result = await handle(payload, config);

    expect(result.linearIssueId).toBe('LINEAR-123');
    expect(calls.length).toBe(1);
    const call = calls[0];
    expect(call.method).toBe('POST');
    expect(call.url).toBe('https://api.linear.app/graphql');
    expect(call.headers.get('authorization')).toBe('Bearer test-key');
    expect(call.json).toBeDefined();
    const body = call.json as { query: string; variables: object };
    expect(body.query).toContain('title: "Test issue"');
    expect(body.query).toContain('description: "Test description');
    expect(body.query).toContain('GitHub Issue: #123');
    expect(body.query).toContain('Reporter: @testuser');
    expect(body.query).toContain('teamId: "TEAM-123"');
    expect(body.query).toContain('labels: ["bug"]');
  });

