    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    const payload = { ...SOURCE_EXAMPLE, action: 'opened' } as GitHubWebhookPayload;
    const config: ConnectorConfig = { linearApiKey: 'k', linearTeamId: 't', fetch };
    await expect(handle(payload, config)).rejects.toThrow('action must be "labeled"');
