    const payload = {
      action: 'labeled',
      issue: { ...SOURCE_EXAMPLE.issue, labels: [{ ...SOURCE_EXAMPLE.issue.labels[0], name: 'feature' }] },
      repository: SOURCE_EXAMPLE.repository,
